const start = { x: -2.5, y: 66, z: 103.5 };

function hasOakLogInScan(scanResult) {
  if (!scanResult) return false;
  if (Array.isArray(scanResult)) {
    return scanResult.some((entry) => entry && (entry.block === 'oak_log' || entry.id === 'oak_log' || entry.type === 'oak_log'));
  }
  if (typeof scanResult === 'object') {
    if (scanResult.oak_log) return true;
    const values = Object.values(scanResult);
    for (const value of values) {
      if (value && typeof value === 'object') {
        if (value.block === 'oak_log' || value.id === 'oak_log' || value.type === 'oak_log') return true;
        if (Array.isArray(value) && value.some((entry) => entry && (entry.block === 'oak_log' || entry.id === 'oak_log' || entry.type === 'oak_log'))) return true;
      }
    }
  }
  return false;
}

function tryMineAndCollect() {
  mc.move_to_block('oak_log', 16, 8000);
  mc.mine_block('oak_log', 8, 1);
  mc.collect('oak_log', 64, 16);
  return mc.count('oak_log') > 0;
}

if (tryMineAndCollect()) {
  console.log('Collected oak_log from a nearby tree.');
} else {
  let found = false;
  for (let radius = 8; radius <= 96 && !found; radius += 8) {
    for (let angle = 0; angle < 360 && !found; angle += 45) {
      const rad = (angle * Math.PI) / 180;
      const x = start.x + Math.cos(rad) * radius;
      const z = start.z + Math.sin(rad) * radius;
      mc.move_to(x, start.y, z, 12000);
      mc.scan(32);
      if (tryMineAndCollect()) {
        found = true;
      }
    }
  }
  if (!found) {
    throw new Error('No oak_log block could be reached or mined.');
  }
  console.log('Explored, mined, and collected oak_log.');
}

const logs = mc.count('oak_log');
if (logs === 0) {
  console.log('No oak logs in inventory; nothing to craft.');
} else {
  const target = logs * 4;
  mc.craft('oak_planks', target);
  console.log('Crafted ' + mc.count('oak_planks') + ' oak planks from ' + logs + ' oak logs.');
}

async function main() {
  const logs = mc.count('oak_planks') === undefined ? 0 : mc.count('oak_log');
  if (logs === 0) {
    console.log('No oak logs to craft.');
    return;
  }
  for (let i = 0; i < logs; i++) {
    await mc.craft('oak_planks', 1);
  }
  console.log('Crafted oak planks; planks now ' + mc.count('oak_planks') + ', logs now ' + mc.count('oak_log') + '.');
}
