  if (!mc.has('crafting_table')) {
    await mc.craft('crafting_table', 1);
  }

  if (!mc.has('crafting_table')) {
    throw new Error('Could not craft crafting_table.');
  }

  try {
    await mc.place_block('crafting_table', Math.round(-2.5), 64, Math.round(103.5));
  } catch (e) {}

  await mc.craft('wooden_pickaxe', 1);

  if (!mc.has('wooden_pickaxe')) {
    throw new Error('wooden_pickaxe was not crafted.');
  }

  console.log('Crafted wooden_pickaxe.');
}

main();

